<article class="recipe"><div class="recipe-top"><div><?php if(!$recipe['is_public']):?><p class="eyebrow">PRIVATE RECIPE</p><?php endif?><h1><?=e($recipe['title'])?></h1><div class="recipe-labels"><?php if($recipe['cuisine_name']):?><span class="cuisine-label"><?=e($recipe['cuisine_name'])?></span><?php endif?><?php foreach($recipeTags as $tag):?><span class="tag-label"><?=e($tag['name'])?></span><?php endforeach?></div><p class="lede"><?=e($recipe['summary'])?></p><p class="byline">By <?=e($recipe['owner_name'])?><?php if($recipe['forked_from_id']):?> · Inspired by <a href="/recipes/<?=$recipe['forked_from_id']?>">recipe #<?=$recipe['forked_from_id']?></a><?php endif?></p></div><div class="actions"><?php $u=App\Auth::user();$owner=$u&&(int)$u['id']===(int)$recipe['user_id'];$admin=$u&&in_array($u['role'],['admin','superadmin'],true);?><?php if($u):?><form method="post" action="/recipes/<?=$recipe['id']?>/favorite"><?=csrf()?><input type="hidden" name="return_to" value="/recipes/<?=$recipe['id']?>"><button class="favorite-button recipe-favorite <?=$isFavorite?'active':''?>" title="<?=$isFavorite?'Remove from favorites':'Add to favorites'?>" aria-label="<?=$isFavorite?'Remove from favorites':'Add to favorites'?>"><?=$isFavorite?'♥':'♡'?></button></form><?php endif?><?php if($owner):?><a class="button" href="/recipes/<?=$recipe['id']?>/edit">Edit recipe</a><?php endif?><?php if($recipe['is_public']&&$u):?><form method="post" action="/recipes/<?=$recipe['id']?>/fork"><?=csrf()?><button class="secondary">Make my version</button></form><?php endif?><?php if($owner||$admin):?><form method="post" action="/recipes/<?=$recipe['id']?>/delete" onsubmit="return confirm('Delete this recipe permanently?')"><?=csrf()?><button class="danger">Delete</button></form><?php endif?></div></div>
<?php if($recipe['source_url']):?><p class="recipe-source">Source<?php if($recipe['source_name']):?> (<?=e($recipe['source_name'])?>)<?php endif?>: <a href="<?=e($recipe['source_url'])?>" target="_blank" rel="noopener noreferrer"><?=e($recipe['source_url'])?></a><?php if($recipe['source_author']):?> by <?=e($recipe['source_author'])?><?php endif?></p><?php endif?>
<?php if($favoritedBy!==null):?><aside class="favorite-summary"><strong>Favorites</strong><?php if($favoritedBy):?><span><?=count($favoritedBy)?> <?=count($favoritedBy)===1?'person has':'people have'?> saved this recipe: <?=e(implode(', ',$favoritedBy))?></span><?php else:?><span>No one has favorited this recipe yet.</span><?php endif?></aside><?php endif?>
<?php if($photos):?><div class="gallery" tabindex="0" aria-label="Recipe photo gallery"><?php foreach($photos as $i=>$p):?><img src="/uploads/<?=e($p['filename'])?>" alt="Photo of <?=e($recipe['title'])?>" <?=$i===0?'class="featured"':''?>><?php endforeach?></div><?php endif?>
<div class="recipe-content"><section class="ingredients"><h2>Ingredients</h2><div class="prose"><?=nl2br(e($recipe['ingredients']))?></div></section><section><h2>Instructions</h2><div class="prose"><?=nl2br(e($recipe['instructions']))?></div><?php if($recipe['notes']):?><div class="notes"><h3>Cook’s notes</h3><div class="prose"><?=nl2br(e($recipe['notes']))?></div></div><?php endif?></section></div></article>
<span data-recipe-view hidden></span>
